import sys
from collections import deque

def bfs(N, M, S):
    queue = deque([(0, 0)])
    visited = [[False] * M for _ in range(N)]
    visited[0][0] = True
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    while queue:
        x, y = queue.popleft()
        if x == N - 1 and y == M - 1:
            return True
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < M and not visited[nx][ny] and S[nx][ny] == '.':
                visited[nx][ny] = True
                queue.append((nx, ny))
    return False

def solve():
    import sys
    input = sys.stdin.read().splitlines()
    index = 0
    T = int(input[index])
    index += 1
    results = []
    for _ in range(T):
        N, M = map(int, input[index].split())
        index += 1
        S = [list(input[index + i]) for i in range(N)]
        index += N
        if bfs(N, M, S):
            results.append(0)
        else:
            rows_with_walls = set()
            for i in range(N):
                for j in range(M):
                    if S[i][j] == '#':
                        rows_with_walls.add(i)
            min_airstrikes = 0
            for row in rows_with_walls:
                for j in range(M):
                    S[row][j] = '.'
                if bfs(N, M, S):
                    min_airstrikes = 1
                    break
                for j in range(M):
                    S[row][j] = '#'
            results.append(min_airstrikes)
    print('\n'.join(map(str, results)))

solve()
